//! M6 type-recovery gate: measure `rdec_core::tyinfer::recover` against truth.
//!
//! `types --corpus` lifts the C corpus (`m4::lift_all` — the same clean pipeline
//! every C gate measures), runs the recovery pass, and scores every parameter
//! and return site against `corpus/truth.tsv` — the declared signature per
//! corpus source, CHECKED IN next to the sources it describes (generated by
//! `scripts/truth_extract.py` and audited by hand; the gate reads the table,
//! it never parses C).
//!
//! Scoring per declared kind:
//!   int    — signedness and width. Width narrower than declared is sound
//!            (the analysis may print a narrower read than the C spells, the
//!            ABI ext moves the rest); width WIDER than declared is a LIE —
//!            the analysis claims the function reads bits the parameter has
//!            no source for. Signedness `signed` over declared `unsigned` is
//!            the classic decompiler bug this gate exists to catch: LIE.
//!   ptr    — the pointer claim scores (only the deref/address rules mint it,
//!            so a pointer claim on an `int` site burns red); signedness and
//!            width of a pointer shape are display choices and not scored.
//!   float  — the float claim scores; an int-grid claim on a float site is
//!            not a lie (the register cell really is read as int by moves).
//! The C corpus declares no float parameters, so on C the float rules must
//! print NOTHING at all — a float claim over an integer site is the same red.
//! The float coverage itself is honest-adjacent: the C++ lane of this command
//! compares recovery to the DEMANGLED declared signature (`param_tys`) and
//! prints it as DECLARED agreement — name evidence, never called independent
//! truth — plus the hand-rule file `crates/core/tests/tyinfer_rules.rs`.
//!
//! Red = any LIE. Silence is never red (an analysis that claims nothing is
//! sound and useless; the counts show which it is).

use crate::m4;
use std::collections::{BTreeMap, HashMap};

use rdec_core::ir::Function;
use rdec_core::ty::{FWidth, Sx, Ty, Width};
use rdec_core::tyinfer::{self, Claim};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Atom {
    Void,
    Int { sx: bool, w: u32 },
    Ptr,
    Flt { w: u32 },
    Unscoreable,
}

fn atom_of(tok: &str) -> Atom {
    match tok {
        "void" => Atom::Void,
        "i8" => Atom::Int { sx: true, w: 8 },
        "u8" => Atom::Int { sx: false, w: 8 },
        "i16" => Atom::Int { sx: true, w: 16 },
        "u16" => Atom::Int { sx: false, w: 16 },
        "i32" => Atom::Int { sx: true, w: 32 },
        "u32" => Atom::Int { sx: false, w: 32 },
        "i64" => Atom::Int { sx: true, w: 64 },
        "u64" => Atom::Int { sx: false, w: 64 },
        "px" | "ppx" => Atom::Ptr,
        "f32" => Atom::Flt { w: 32 },
        "f64" => Atom::Flt { w: 64 },
        _ => Atom::Unscoreable,
    }
}

struct Decl {
    ret: Atom,
    params: Vec<Atom>,
}

fn load_truth() -> Result<HashMap<String, Decl>, String> {
    let text = std::fs::read_to_string("corpus/truth.tsv")
        .map_err(|e| format!("corpus/truth.tsv: {e}"))?;
    let mut out = HashMap::new();
    for line in text.lines() {
        let line = line.trim_end_matches('\r');
        if line.is_empty() || line.starts_with('#') || line.starts_with("name\t") {
            continue;
        }
        let cols: Vec<&str> = line.split('\t').collect();
        if cols.len() < 3 {
            return Err(format!("truth row too short: {line}"));
        }
        let params = if cols.get(2).copied().unwrap_or("").trim().is_empty() {
            Vec::new()
        } else {
            cols[2].split(';').map(|t| atom_of(t.trim())).collect()
        };
        out.insert(
            cols[0].to_string(),
            Decl {
                ret: atom_of(cols[1].trim()),
                params,
            },
        );
    }
    Ok(out)
}

#[derive(Default)]
struct Census {
    scored: usize,
    sites: usize,
    no_truth: usize,
    sx_exact: usize,
    sx_display: usize,
    sx_silent: usize,
    sx_lie: usize,
    w_exact: usize,
    w_narrow: usize,
    w_lie: usize,
    ptr_yes: usize,
    ptr_lie: usize,
    flt_yes: usize,
    flt_lie: usize,
    void_yes: usize,
    void_lie: usize,
    cf_sx: usize,
    cf_slot: usize,
    cf_flt: usize,
    lies: Vec<String>,
    cpp_sites: usize,
    cpp_agree: usize,
    cpp_disagree: Vec<String>,
}

fn w_bits(w: Width) -> u32 {
    match w {
        Width::W1 => 1,
        Width::W8 => 8,
        Width::W16 => 16,
        Width::W32 => 32,
        Width::W64 => 64,
    }
}

fn score_int_grid(who: &str, claim: &Claim, truth: Atom, c: &mut Census, ret: bool) {
    let tag = if ret { " (ret)" } else { "" };
    match truth {
        Atom::Int { sx, w } => {
            match claim.sx {
                Some(cs) => {
                    let ts = if sx { Sx::Signed } else { Sx::Unsigned };
                    if cs == ts {
                        c.sx_exact += 1;
                    } else {
                        c.sx_lie += 1;
                        c.lies.push(format!(
                            "{who}{tag}: prints {} over declared {}",
                            if cs == Sx::Signed {
                                "signed"
                            } else {
                                "unsigned"
                            },
                            if sx { "signed" } else { "unsigned" }
                        ));
                    }
                }
                // Signedness unforced. If width IS forced, the printed form
                // is canonical-signed (`int32_t`): it matches a signed
                // declaration exactly, and displays (does not assert) over an
                // unsigned one. With no width forced the site is silent.
                None => {
                    if claim.width.is_some() && !claim.ptr && claim.flt.is_none() {
                        if sx {
                            c.sx_exact += 1;
                        } else {
                            c.sx_display += 1;
                        }
                    } else {
                        c.sx_silent += 1;
                    }
                }
            }
            if let Some(cw) = claim.width {
                let cb = w_bits(cw);
                if cb == w {
                    c.w_exact += 1;
                } else if cb < w {
                    c.w_narrow += 1;
                } else {
                    c.w_lie += 1;
                    c.lies
                        .push(format!("{who}{tag}: reads w{cb} over declared w{w}"));
                }
            }
            if claim.ptr {
                c.ptr_lie += 1;
                c.lies
                    .push(format!("{who}{tag}: pointer claim over declared int"));
            }
            if claim.flt.is_some() {
                c.flt_lie += 1;
                c.lies
                    .push(format!("{who}{tag}: float claim over declared int"));
            }
        }
        Atom::Ptr => {
            if claim.ptr {
                c.ptr_yes += 1;
            }
            if claim.flt.is_some() {
                c.flt_lie += 1;
                c.lies
                    .push(format!("{who}{tag}: float claim over declared pointer"));
            }
        }
        Atom::Flt { w } => {
            match claim.flt {
                Some(FWidth::F32) if w == 32 => c.flt_yes += 1,
                Some(FWidth::F64) if w == 64 => c.flt_yes += 1,
                Some(fc) => {
                    c.flt_lie += 1;
                    c.lies
                        .push(format!("{who}{tag}: float claim {fc:?} over declared f{w}"));
                }
                None => {}
            }
            if claim.ptr {
                c.ptr_lie += 1;
                c.lies
                    .push(format!("{who}{tag}: pointer claim over declared float"));
            }
        }
        Atom::Void | Atom::Unscoreable => {}
    }
}

fn score_return(who: &str, sig: &tyinfer::Signature, truth: Atom, c: &mut Census) {
    c.sites += 1;
    match truth {
        Atom::Void => {
            // Under the integer model the lifter records a return cell in
            // every function; the honest question is whether the returned
            // value carries any claim at all. A silent return claim matches
            // a void declaration; a FORCED one (the epilogue value provably
            // does signed work / survives as the answer) is over truth.
            if sig.void_return || sig.ret.is_silent() {
                c.void_yes += 1;
            } else {
                c.void_lie += 1;
                c.lies
                    .push(format!("{who}: return claim over declared void"));
            }
        }
        truth => score_int_grid(who, &sig.ret, truth, c, true),
    }
}

/// The C++ lane: declared-signature parity. `param_tys` came from the mangled
/// name (name evidence), so this CORROBORATES the recovery on float-shaped
/// parameters and is printed as such — never as independent truth.
fn cpp_parity(f: &Function, name: &str, c: &mut Census) {
    let sig = tyinfer::recover(f);
    for (i, pt) in f.param_tys.iter().enumerate() {
        let Some(claim) = sig.params.get(i) else {
            break;
        };
        c.cpp_sites += 1;
        let declared_float = matches!(pt, Ty::Float { .. });
        let agree = match (declared_float, claim.flt) {
            (true, Some(fc)) => match pt {
                Ty::Float { w } => {
                    matches!((fc, *w as u32), (FWidth::F32, 32) | (FWidth::F64, 64))
                }
                _ => false,
            },
            (true, None) => false,
            (false, None) => true,
            (false, Some(_)) => false,
        };
        if agree {
            c.cpp_agree += 1;
        } else {
            c.cpp_disagree.push(format!(
                "{name}#p{i}: claim {:?} over declared {pt:?}",
                claim.flt
            ));
        }
    }
}

/// The family key of a printed LIE line: `subject|kind`.
///
/// It is DERIVED from the scorer's own text on purpose: a second, parallel
/// bookkeeping counter is the shape that silently stops counting. The five
/// classes are the five the scorer can print; anything else maps to
/// `UNMAPPED(...)`, which matches no baseline row, so a NEW lie class reddens
/// the ratchet instead of hiding in an unmapped string.
fn lie_family(text: &str) -> String {
    let (who, tail) = match text.split_once(':') {
        Some((w, t)) => (w.trim(), t.trim()),
        None => (text.trim(), ""),
    };
    let who = who.replace(" (ret)", "");
    let kind = if tail.starts_with("prints ") {
        "signedness"
    } else if tail.starts_with("reads ") {
        "width"
    } else if tail.starts_with("pointer claim") {
        "pointer"
    } else if tail.starts_with("float claim") {
        "float"
    } else if tail.starts_with("return claim") {
        "void-return"
    } else {
        return format!("UNMAPPED({tail})");
    };
    format!("{who}|{kind}")
}

/// Read a `subject|kind COUNT` baseline (blank and `#` lines ignored).
fn load_types_baseline(path: &str) -> Result<BTreeMap<String, usize>, String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("{path}: {e}"))?;
    let mut out: BTreeMap<String, usize> = BTreeMap::new();
    for line in text.lines() {
        let line = line.trim_end_matches('\r');
        let t = line.trim();
        if t.is_empty() || t.starts_with('#') {
            continue;
        }
        let mut cols = t.split_whitespace();
        let (Some(key), Some(cnt)) = (cols.next(), cols.next()) else {
            return Err(format!("{path}: baseline row too short: {line}"));
        };
        let Ok(n) = cnt.parse::<usize>() else {
            return Err(format!("{path}: baseline count is not a number: {line}"));
        };
        if cols.next().is_some() {
            return Err(format!("{path}: extra columns in baseline row: {line}"));
        }
        out.insert(key.to_string(), n);
    }
    if out.is_empty() {
        return Err(format!(
            "{path}: baseline is empty (a gate that checks nothing must not pass)"
        ));
    }
    Ok(out)
}

/// Compare a census's lie families with the baseline. Fails on a RISE (new
/// over-truth claims), on a FALL (the commit must lower the baseline in the same
/// change, the `.gate/unwrap-baseline` rule) and on any family with no row.
fn ratchet_problems(got: &BTreeMap<String, usize>, want: &BTreeMap<String, usize>) -> Vec<String> {
    let mut p = Vec::new();
    for (k, w) in want.iter() {
        match got.get(k) {
            None => p.push(format!(
                "{k}: baseline allows {w}, census has 0 — lower the baseline in this commit"
            )),
            Some(g) if g > w => p.push(format!(
                "{k}: {} claims, baseline allows {w} — NEW over-truth claims",
                g
            )),
            Some(g) if g < w => p.push(format!(
                "{k}: {} claims, baseline allows {w} — lower the baseline in this commit",
                g
            )),
            Some(_) => {}
        }
    }
    for (k, g) in got.iter() {
        if !want.contains_key(k) {
            p.push(format!(
                "{k}: {g} claims and NO baseline row — a new lie family: fix the pass, or name it in the baseline in this commit"
            ));
        }
    }
    p
}

fn families_of(lies: &[String]) -> BTreeMap<String, usize> {
    let mut m: BTreeMap<String, usize> = BTreeMap::new();
    for l in lies.iter() {
        *m.entry(lie_family(l)).or_insert(0) += 1;
    }
    m
}

/// `types --corpus --baseline [PATH]`: the CI form of this gate. The census
/// printed is the SAME census, and the scorer is untouched — what the baseline
/// changes is the exit code: a green run is "the census equals the named, known
/// lies exactly". `rdec types --corpus` on its own keeps reporting the raw
/// verdict (exit 1 while any lie stands).
fn baseline_arg(args: &[String]) -> Option<String> {
    let i = args.iter().position(|a| a == "--baseline")?;
    match args.get(i + 1) {
        Some(p) if !p.starts_with("--") => Some(p.clone()),
        _ => Some(".gate/types-baseline".to_string()),
    }
}

/// The object-file arguments of `types`: every positional, minus a
/// `--baseline PATH` value (which is a baseline file, not an object).
fn object_args(args: &[String]) -> Vec<String> {
    let bl_value_index = args.iter().position(|a| a == "--baseline").map(|i| i + 1);
    args.iter()
        .enumerate()
        .skip(1)
        .filter(|(i, a)| !a.starts_with("--") && bl_value_index != Some(*i))
        .map(|(_, a)| a.clone())
        .collect()
}

pub fn cmd_types(args: &[String]) -> i32 {
    if let Some(pos) = args.iter().position(|a| a == "--explain") {
        return cmd_explain(args.get(pos + 1));
    }
    if args.iter().any(|a| a == "--selftest") {
        return types_selftest();
    }
    let mut files: Vec<String> = Vec::new();
    let mut keys: HashMap<String, String> = HashMap::new();
    let corpus = args.iter().any(|a| a == "--corpus");
    if corpus {
        let man = match std::fs::read_to_string("corpus/manifest.tsv") {
            Ok(m) => m,
            Err(e) => {
                eprintln!("corpus/manifest.tsv: {e}");
                return 2;
            }
        };
        for line in man.lines() {
            if line.starts_with('#') || line.starts_with("name\t") {
                continue;
            }
            let cols: Vec<&str> = line.split('\t').collect();
            if cols.len() >= 3 {
                keys.insert(cols[2].to_string(), cols[0].to_string());
                files.push(cols[2].to_string());
            }
        }
    }
    // The positional args are objects; a `--baseline PATH` value is NOT (measured: the
    // first version skipped the flag's own index, so `.gate/types-baseline` went to
    // the COFF loader and the CI form died with "object with a 28515-byte optional
    // header", exit 2). Pinned by baseline_arg_split_pins_the_baseline_path_value.
    let baseline = baseline_arg(args);
    files.extend(object_args(args));
    if files.is_empty() {
        eprintln!("usage: rdec types --corpus");
        return 2;
    }
    let truth = match load_truth() {
        Ok(t) => t,
        Err(e) => {
            eprintln!("{e}");
            return 2;
        }
    };
    let subjects = match m4::lift_all(&files) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("types: lift: {e}");
            return 2;
        }
    };
    let mut c = Census::default();
    for s in subjects.iter() {
        if s.sym.starts_with("__Z") || s.sym.contains("?") {
            cpp_parity(&s.f, &s.sym, &mut c);
            continue;
        }
        let key = keys.get(&s.obj).cloned().unwrap_or_default();
        let Some(decl) = truth.get(&key) else {
            c.no_truth += 1;
            continue;
        };
        c.scored += 1;
        let sig = tyinfer::recover(&s.f);
        c.cf_sx += sig.sx_conflicts;
        for (i, claim) in sig.params.iter().enumerate() {
            c.sites += 1;
            c.cf_slot += usize::from(claim.slot_conflict);
            c.cf_flt += usize::from(claim.flt_conflict);
            match decl.params.get(i) {
                Some(atom) => score_int_grid(&format!("{key}#p{i}"), claim, *atom, &mut c, false),
                None => c.no_truth += 1,
            }
        }
        score_return(&key, &sig, decl.ret, &mut c);
    }
    println!("== M6 type recovery: C corpus vs truth.tsv ==");
    println!(
        "functions scored: {scored}   sites: {sites}   unscoreable (no truth row): {no_truth}",
        scored = c.scored,
        sites = c.sites,
        no_truth = c.no_truth
    );
    println!(
        "signedness  exact {}   canonical-display-over-unsigned {}   sound-silent {}   LIE {}",
        c.sx_exact, c.sx_display, c.sx_silent, c.sx_lie
    );
    println!(
        "width       exact {}   narrower(sound) {}   WIDER-LIE {}",
        c.w_exact, c.w_narrow, c.w_lie
    );
    println!(
        "pointer     on-ptr {}   LIE(ptr over int/float) {}",
        c.ptr_yes, c.ptr_lie
    );
    println!(
        "float       on-float {}   LIE(float over int/ptr) {}",
        c.flt_yes, c.flt_lie
    );
    println!("void-return matches {}   LIE {}", c.void_yes, c.void_lie);
    println!(
        "recorded conflicts (loud by design): signedness {} slot {} precision {}",
        c.cf_sx, c.cf_slot, c.cf_flt
    );
    for l in c.lies.iter().take(40) {
        println!("  LIE: {l}");
    }
    println!(
        "C++ declared-parity (name evidence, not truth): {}/{}{}",
        c.cpp_agree,
        c.cpp_sites,
        if c.cpp_disagree.is_empty() {
            String::new()
        } else {
            format!("  DISAGREE: {}", c.cpp_disagree.join(" | "))
        }
    );
    let red = c.sx_lie + c.w_lie + c.ptr_lie + c.flt_lie + c.void_lie;
    if let Some(path) = baseline.as_deref() {
        // The CI form: print the census, then ratchet it against the named, known
        // lies. The scorer is untouched — every LIE line above is printed, and a
        // rise OR a fall in any family is red, exactly like `.gate/unwrap-baseline`.
        let want = match load_types_baseline(path) {
            Ok(w) => w,
            Err(e) => {
                eprintln!("{e}");
                return 2;
            }
        };
        let got = families_of(&c.lies);
        for (k, v) in got.iter() {
            println!(
                "  family {k} = {v} (baseline {})",
                want.get(k).copied().unwrap_or(0)
            );
        }
        let problems = ratchet_problems(&got, &want);
        for p in problems.iter() {
            println!("  RATCHET: {p}");
        }
        if problems.is_empty() {
            println!("gate: types BASELINE GREEN ({red} named over-truth claims, 0 new, {path})");
            return 0;
        }
        println!(
            "gate: types BASELINE RED ({} ratchet problems; raw census red = {red})",
            problems.len()
        );
        return 1;
    }
    if red > 0 {
        println!("gate: types RED ({red} over-truth claims)");
        return 1;
    }
    println!("gate: types GREEN (no over-truth claims)");
    0
}

/// `types --explain <stem>`: print, for one corpus function, every fact that
/// landed on every parameter and on the returned value, with the address of
/// the instruction that stated it — the audit view the census numbers are
/// supposed to be checkable against.
fn cmd_explain(target: Option<&String>) -> i32 {
    let Some(target) = target else {
        eprintln!("usage: rdec types --explain <corpus-stem>");
        return 2;
    };
    // Accept `stem` (first matching opt) or `stem.OPT` to pin one object.
    let (stem, opt_wanted) = match target.rsplit_once('.') {
        Some((n, o)) if matches!(o, "O0" | "O1" | "O2") => (n.to_string(), Some(o.to_string())),
        _ => (target.clone(), None),
    };
    let target = stem;
    let man = match std::fs::read_to_string("corpus/manifest.tsv") {
        Ok(m) => m,
        Err(e) => {
            eprintln!("corpus/manifest.tsv: {e}");
            return 2;
        }
    };
    let truth = match load_truth() {
        Ok(t) => t,
        Err(e) => {
            eprintln!("{e}");
            return 2;
        }
    };
    for line in man.lines() {
        if line.starts_with('#') || line.starts_with("name\t") {
            continue;
        }
        let cols: Vec<&str> = line.split('\t').collect();
        if cols.len() < 3 || cols[0] != target {
            continue;
        }
        // The old spelling guarded an `as_deref()` unwrap by hand with
        // `opt_wanted.is_some()`, which is exactly the shape the panic-site ratchet
        // exists to remove. Bind the value instead of asserting it is there.
        if let Some(ow) = opt_wanted.as_deref() {
            if cols[1] != ow {
                continue;
            }
        }
        let subjects = match m4::lift_all(&[cols[2].to_string()]) {
            Ok(s) => s,
            Err(e) => {
                eprintln!("lift: {e}");
                return 2;
            }
        };
        let Some(s) = subjects.iter().find(|s| !s.sym.starts_with("__Z")) else {
            eprintln!("no subject in {}", cols[2]);
            continue;
        };
        let sig = tyinfer::recover(&s.f);
        let mut at: HashMap<u64, String> = HashMap::new();
        for blk in s.f.blocks.iter() {
            for ins in blk.instrs.iter() {
                at.entry(ins.addr)
                    .and_modify(|s| *s += &format!(" | v{} = {:?}", ins.dest, ins.op))
                    .or_insert_with(|| format!("v{} = {:?}", ins.dest, ins.op));
            }
        }
        let show = |fs: &[rdec_core::tyinfer::FactSite]| -> String {
            fs.iter()
                .map(|f| {
                    format!(
                        "{}@{:#x}[{}]",
                        f.fact.describe(),
                        f.addr,
                        at.get(&f.addr).cloned().unwrap_or_default()
                    )
                })
                .collect::<Vec<_>>()
                .join(" ")
        };
        println!("{} ({})  ret_ty={:?}", target, s.obj, s.f.ret_ty);
        if let Some(d) = truth.get(&target) {
            println!("truth: ret {:?} params {:?}", d.ret, d.params);
        }
        println!(
            "params: {} cells, param_tys {:?}",
            s.f.params.len(),
            s.f.param_tys
        );
        for (i, &vid) in s.f.params.iter().enumerate() {
            println!(
                "p{i} (v{vid}): claim {:?} own-facts {}",
                sig.params.get(i).map(|c| c.c_type()),
                show(
                    &sig.fact_witness
                        .get(vid as usize)
                        .cloned()
                        .unwrap_or_default()
                )
            );
            // Facts on the seed's chain (uses of the parameter) are the usual
            // source of a claim: list them once, under the first parameter.
            if i > 0 {
                continue;
            }
            let mut hops = Vec::new();
            for (v, fs) in sig.fact_witness.iter().enumerate() {
                if v as u32 != vid && !fs.is_empty() {
                    hops.push((v, fs.clone()));
                }
            }
            hops.sort_by_key(|(v, _)| *v);
            for (v, fs) in hops.into_iter().take(24) {
                println!("   v{v} facts {}", show(&fs));
            }
        }
        for (bi, b) in s.f.blocks.iter().enumerate() {
            if let rdec_core::ir::Terminator::Return(v) = &b.term {
                println!(
                    "return bb{bi} v{v}: claim {:?} facts {}",
                    sig.ret.c_type(),
                    show(
                        &sig.fact_witness
                            .get(*v as usize)
                            .cloned()
                            .unwrap_or_default()
                    )
                );
            }
        }
        println!("void_return: {}", sig.void_return);
        return 0;
    }
    eprintln!("no manifest row named {target}");
    2
}

// ---------------------------------------------------------------------------
// types --selftest: the forcing drill.
//
// Every line is a RULE and a FIXTURE that binds it: the IR that must feed a
// claim, checked after recovery. A rule whose object disappears (registers
// merged, a pass deleted) spots its probe false, the probe line names it, and
// - because the register gate refuses an empty battery - the selftest prints
// 0/22 and fails. `types --corpus` reports; this command enforces.
// ---------------------------------------------------------------------------

/// A fixture: cells (a, b, c) as W64 parameter cells, body ops appended in the
/// entry block, one Return. Every probe is a fact pattern, not a whole
/// function; `finish` supplies the ABI (params, return type, terminator) a
/// verifier and a recovery pass both insist on.
struct Probe {
    f: Function,
    cells: Vec<rdec_core::ir::VId>,
    /// Body instructions get distinct machine addresses: a fact is keyed by
    /// (fact, address), so two statements about one value are two witnesses
    /// only if they come from two instructions.
    at: u64,
}

impl Probe {
    fn new(n: usize) -> Probe {
        use rdec_core::ir::{Op, NO_VAL};
        let mut f = Function::new("probe", 0x1000);
        let mut cells = Vec::new();
        for i in 0..n {
            cells.push(f.emit(f.entry, Op::Param, Ty::u64(), (0x10 + i as u64) * 8));
        }
        f.block_mut(f.entry).term = Terminator::Return(NO_VAL);
        Probe {
            f,
            cells,
            at: 0x2000,
        }
    }

    fn cell_w32(&mut self, i: usize) {
        let v = self.cells[i];
        self.f.set_ty(v, Ty::int(Width::W32, Sx::Unsigned));
    }

    /// The cell is a pointer shape (the argparse/`array_walk` cell: W64 bits
    /// that are an address, so the analysis must see W64 width and `ptr`).
    fn cell_ptr(&mut self, i: usize) {
        let v = self.cells[i];
        self.f.set_ty(v, Ty::void_ptr());
    }

    /// A parameter cell of a given shape, appended and bound into `params`.
    fn param(&mut self, ty: Ty) -> rdec_core::ir::VId {
        let entry = self.f.entry;
        let v = self.f.emit(entry, Op::Param, ty, 0x900);
        self.cells.push(v);
        v
    }

    fn ins(&mut self, op: Op, ty: Ty) -> rdec_core::ir::VId {
        let entry = self.f.entry;
        let at = self.at;
        self.at += 8;
        self.f.emit(entry, op, ty, at)
    }

    fn ins_void(&mut self, op: Op) {
        let entry = self.f.entry;
        let at = self.at;
        self.at += 8;
        self.f.emit_void(entry, op, at);
    }

    /// One basic block split (`bb1` true-branch, `bb2` join): the shape a phi
    /// needs, and the shape the verifier checks the phi's edges against.
    fn split(&mut self, cond: rdec_core::ir::VId) -> [rdec_core::ir::BbId; 3] {
        use rdec_core::ir::Terminator;
        let e = self.f.entry;
        let b1 = self.f.new_block(0x3000);
        let b2 = self.f.new_block(0x4000);
        self.f.block_mut(e).term = Terminator::Branch {
            cond,
            then_bb: b1,
            else_bb: b2,
        };
        [e, b1, b2]
    }

    /// Branch the entry and add the join: `[edge, merge]`. A phi in `merge`
    /// names exactly these two predecessors — the multiset the SSA verifier
    /// checks every incoming list against.
    fn split_merge(&mut self, cond: rdec_core::ir::VId) -> [rdec_core::ir::BbId; 2] {
        let e = self.f.entry;
        let b1 = self.f.new_block(0x3000);
        let b2 = self.f.new_block(0x4000);
        self.f.block_mut(e).term = Terminator::Branch {
            cond,
            then_bb: b1,
            else_bb: b2,
        };
        [b1, b2]
    }

    /// Bind the ABI the recovery and the verifier both insist on: every block
    /// that is still `Unreachable` answers with `answer`, `params` names the
    /// cells in signature order, and the return cell is W64.
    fn finish(&mut self, answer: rdec_core::ir::VId) {
        for i in 0..self.f.blocks.len() {
            let b = self.f.blocks[i].id;
            if matches!(self.f.block(b).term, Terminator::Unreachable) {
                self.f.block_mut(b).term = Terminator::Return(answer);
            }
        }
        self.f.params = self.cells.clone();
        self.f.ret_ty = Ty::u64();
    }
}

use rdec_core::ir::{BinOp, CastKind, FlagsOp, IntCmp, Op, Terminator, VId};

/// The `Load`/`Store` home in these fixtures: a constant frame address, which
/// the slot key reads as (self, 0) — a frame slot that is not a parameter.
fn frame(probe: &mut Probe) -> VId {
    probe.ins(Op::Const(0x8000), Ty::u64())
}

fn konst(probe: &mut Probe, v: u64) -> VId {
    probe.ins(Op::Const(v), Ty::u64())
}

fn probe_zext() -> bool {
    // `movzx rax, ecx` where ecx IS the cell: the zero fill is a machine fact
    // about the cell's high half, so the cell prints unsigned. The promote
    // pair (a 32-bit read of the W64 cell plus the zero-extend) is the SPILL
    // shape: a signed `int` spilled looks byte-identical, so that witness is
    // about the copy, not the cell, and the cell prints canonical-signed
    // (`sx_promote_silent`, ruled in `tyinfer`, not this probe).
    let mut p = Probe::new(1);
    let a = p.cells[0];
    p.cell_w32(0);
    let z = p.ins(Op::Cast(CastKind::ZExt, Ty::u64(), a), Ty::u64());
    p.finish(z);
    if !rdec_core::verify::verify(&p.f).is_ok() {
        return false;
    }
    let sig = tyinfer::recover(&p.f);
    sig.params[0].sx == Some(Sx::Unsigned)
}

fn probe_sext() -> bool {
    // `movsx rax, ecx`: the copy of bit 31 into the high half is a sign.
    let mut p = Probe::new(1);
    let a = p.cells[0];
    let t = p.ins(Op::Cast(CastKind::Trunc, Ty::u32(), a), Ty::u32());
    let s = p.ins(Op::Cast(CastKind::SExt, Ty::u64(), t), Ty::u64());
    p.finish(s);
    if !rdec_core::verify::verify(&p.f).is_ok() {
        return false;
    }
    tyinfer::recover(&p.f).params[0].sx == Some(Sx::Signed)
}

fn probe_shr_zero_fill() -> bool {
    // `shr` fills with zeroes, which is the unsigned reading of the same bits;
    // `sar` (probe 3's twin, see probe 19) fills with the sign.
    let mut p = Probe::new(1);
    let a = p.cells[0];
    let n = konst(&mut p, 1);
    let s = p.ins(Op::Bin(BinOp::Shr, a, n), Ty::u64());
    p.finish(s);
    if !rdec_core::verify::verify(&p.f).is_ok() {
        return false;
    }
    tyinfer::recover(&p.f).params[0].sx == Some(Sx::Unsigned)
}

fn probe_sdiv() -> bool {
    let mut p = Probe::new(1);
    let a = p.cells[0];
    let d = konst(&mut p, 1);
    let q = p.ins(Op::Bin(BinOp::SDiv, a, d), Ty::u64());
    p.finish(q);
    if !rdec_core::verify::verify(&p.f).is_ok() {
        return false;
    }
    tyinfer::recover(&p.f).params[0].sx == Some(Sx::Signed)
}

fn probe_udiv() -> bool {
    let mut p = Probe::new(1);
    let a = p.cells[0];
    let d = konst(&mut p, 1);
    let q = p.ins(Op::Bin(BinOp::UDiv, a, d), Ty::u64());
    p.finish(q);
    if !rdec_core::verify::verify(&p.f).is_ok() {
        return false;
    }
    tyinfer::recover(&p.f).params[0].sx == Some(Sx::Unsigned)
}

fn probe_cmp(base: IntCmp) -> bool {
    // `cmp` + `jl`/`jb` is a promise about BOTH sides: the other signedness
    // would be a different answer, so the compare marks every operand it reads.
    let mut p = Probe::new(2);
    let (a, b) = (p.cells[0], p.cells[1]);
    let c = p.ins(Op::Cmp(base, a, b), Ty::Bool);
    p.split(c);
    p.finish(a);
    if !rdec_core::verify::verify(&p.f).is_ok() {
        return false;
    }
    let sig = tyinfer::recover(&p.f);
    let want = match base {
        IntCmp::Lt => Sx::Signed,
        _ => Sx::Unsigned,
    };
    sig.params[0].sx == Some(want) && sig.params[1].sx == Some(want)
}

fn probe_sitofp() -> bool {
    // `cvtsi2sd` converts a SIGNED integer; a source without a sign has no
    // answer for it, so the conversion is evidence about the source.
    let mut p = Probe::new(1);
    let a = p.cells[0];
    let flt = p.ins(Op::Cast(CastKind::SIToFp, Ty::f64(), a), Ty::f64());
    // RAX is the answer in these fixtures: the float cell is moved out as the
    // W64 it is, and the probe is about the source, not the return type.
    let bits = p.ins(Op::Cast(CastKind::Bitcast, Ty::u64(), flt), Ty::u64());
    p.finish(bits);
    if !rdec_core::verify::verify(&p.f).is_ok() {
        return false;
    }
    tyinfer::recover(&p.f).params[0].sx == Some(Sx::Signed)
}

fn probe_uitofp() -> bool {
    let mut p = Probe::new(1);
    let a = p.cells[0];
    let flt = p.ins(Op::Cast(CastKind::UIToFp, Ty::f64(), a), Ty::f64());
    let bits = p.ins(Op::Cast(CastKind::Bitcast, Ty::u64(), flt), Ty::u64());
    p.finish(bits);
    if !rdec_core::verify::verify(&p.f).is_ok() {
        return false;
    }
    tyinfer::recover(&p.f).params[0].sx == Some(Sx::Unsigned)
}

fn probe_ptr_from_deref() -> bool {
    // Pointerness is a fact about the value that IS the address. `p + i*8` in
    // the load's address marks `p`; the sum node and the integer index do not
    // earn one, and an addition of integers never manufactures one.
    let mut p = Probe::new(2);
    let (ptr, idx) = (p.cells[0], p.cells[1]);
    p.cell_ptr(0);
    let eight = p.ins(Op::Const(8), Ty::u64());
    let scaled = p.ins(Op::Bin(BinOp::Mul, idx, eight), Ty::u64());
    let addr = p.ins(Op::Bin(BinOp::Add, ptr, scaled), Ty::void_ptr());
    let v = p.ins(Op::Load(Ty::u64(), addr), Ty::u64());
    p.finish(v);
    if !rdec_core::verify::verify(&p.f).is_ok() {
        return false;
    }
    let sig = tyinfer::recover(&p.f);
    sig.params[0].ptr && !sig.params[1].ptr
}

fn probe_ptr_plus_const() -> bool {
    // `mov rax, [p+8]`: the constant is the field offset, the pointer is the
    // base — the claim belongs to the base and survives the addition.
    let mut p = Probe::new(0);
    let base = p.param(Ty::void_ptr());
    let off = p.ins(Op::Const(0x10), Ty::u64());
    let addr = p.ins(Op::Bin(BinOp::Add, base, off), Ty::void_ptr());
    let v = p.ins(Op::Load(Ty::u64(), addr), Ty::u64());
    p.finish(v);
    if !rdec_core::verify::verify(&p.f).is_ok() {
        return false;
    }
    tyinfer::recover(&p.f).params[0].ptr
}

fn probe_slot_link() -> bool {
    // The -O0 spill shape: `mov [rbp-8],ecx` then `mov eax,[rbp-8]` and a
    // `movsx` of the reload. The slot is the only edge between the two
    // values, so a signedness fact on the loaded value reaches the stored
    // one: `claim_of` folds signedness across `value_slot` and the SExt
    // ranks first, landing the stored cell Signed (`int32_t`), never silent.
    let mut p = Probe::new(1);
    let a = p.cells[0];
    let slot = frame(&mut p);
    p.ins_void(Op::Store(Ty::u32(), slot, a));
    let v = p.ins(Op::Load(Ty::u32(), slot), Ty::u32());
    let e = p.ins(Op::Cast(CastKind::SExt, Ty::u64(), v), Ty::u64());
    p.finish(e);
    if !rdec_core::verify::verify(&p.f).is_ok() {
        return false;
    }
    tyinfer::recover(&p.f).params[0].sx == Some(Sx::Signed)
}

fn probe_cell32_sext_width() -> bool {
    // A 32-bit cell read and sign-extended: both the cell (its own width) and
    // the `movsx` vote, and they agree on `int32_t`.
    let mut p = Probe::new(1);
    let a = p.cells[0];
    p.cell_w32(0);
    let e = p.ins(Op::Cast(CastKind::SExt, Ty::u64(), a), Ty::u64());
    p.finish(e);
    if !rdec_core::verify::verify(&p.f).is_ok() {
        return false;
    }
    let c = &tyinfer::recover(&p.f).params[0];
    c.sx == Some(Sx::Signed) && c.width == Some(Width::W32)
}

fn probe_w64_read_no_width() -> bool {
    // W64 is the cell's starting width: reading all of it bounds nothing, so
    // the width claim stays silent.
    let mut p = Probe::new(1);
    let a = p.cells[0];
    let one = konst(&mut p, 1);
    let s = p.ins(Op::Bin(BinOp::Add, a, one), Ty::u64());
    p.finish(s);
    if !rdec_core::verify::verify(&p.f).is_ok() {
        return false;
    }
    let c = &tyinfer::recover(&p.f).params[0];
    c.width.is_none()
}

fn probe_spill_bounds_width() -> bool {
    // `mov dword [rbp-8], ecx` after narrowing the cell: the 32-bit home is a
    // ceiling on what can come back out, and the bound travels with the trunc.
    let mut p = Probe::new(1);
    let a = p.cells[0];
    let tr = p.ins(Op::Cast(CastKind::Trunc, Ty::u32(), a), Ty::u32());
    let slot = frame(&mut p);
    p.ins_void(Op::Store(Ty::u32(), slot, tr));
    p.finish(tr);
    if !rdec_core::verify::verify(&p.f).is_ok() {
        return false;
    }
    tyinfer::recover(&p.f).params[0].width == Some(Width::W32)
}

fn probe_signedness_does_not_leak_across_slots() -> bool {
    // Two homes, one int store each; no sign-bearing op anywhere. Signedness
    // is per-value: a slot is an address, not a type, and it cannot pick one.
    let mut p = Probe::new(2);
    let (a, b) = (p.cells[0], p.cells[1]);
    let s1 = frame(&mut p);
    let s2 = p.ins(Op::Const(0x8008), Ty::u64());
    p.ins_void(Op::Store(Ty::u64(), s1, a));
    p.ins_void(Op::Store(Ty::u64(), s2, b));
    let x = p.ins(Op::Load(Ty::u64(), s1), Ty::u64());
    p.finish(x);
    if !rdec_core::verify::verify(&p.f).is_ok() {
        return false;
    }
    let sig = tyinfer::recover(&p.f);
    sig.params[0].sx.is_none() && sig.params[1].sx.is_none()
}

fn probe_width_claim_carries_witness() -> bool {
    // A claim is a claim because a stated fact supports it: the witness list
    // of a width claim is never empty and names the read width.
    let mut p = Probe::new(1);
    let a = p.cells[0];
    let tr = p.ins(Op::Cast(CastKind::Trunc, Ty::u32(), a), Ty::u32());
    p.finish(tr);
    if !rdec_core::verify::verify(&p.f).is_ok() {
        return false;
    }
    let sig = tyinfer::recover(&p.f);
    let c = &sig.params[0];
    c.width.is_some()
        && sig
            .fact_witness
            .get(a as usize)
            .map(|w| !w.is_empty())
            .unwrap_or(false)
}

fn probe_width_stops_at_phi() -> bool {
    // The two edges of a merge: one arrives through a 32-bit cell read, the
    // other uses the W64 cell whole. A bound that crossed the phi would print
    // `int32_t` for a value the second edge proves needs 64 bits.
    let mut p = Probe::new(2);
    let (a, b) = (p.cells[0], p.cells[1]);
    // Edge 1 narrows `a` to a 32-bit read, so `a`'s claim is `int32_t` and the
    // phi's first edge carries that bound; edge 2 uses `b`'s cell whole.
    let a32 = p.ins(Op::Cast(CastKind::Trunc, Ty::u32(), a), Ty::u32());
    let e = p.ins(Op::Cast(CastKind::SExt, Ty::u64(), a32), Ty::u64());
    let one = konst(&mut p, 1);
    let s = p.ins(Op::Bin(BinOp::Add, b, one), Ty::u64());
    let zero = p.ins(Op::Const(0), Ty::Bool);
    let [b1, b2] = p.split_merge(zero);
    let phi = p.f.emit(
        b2,
        Op::Phi(vec![(e, b1), (s, b2)].into_boxed_slice()),
        Ty::u64(),
        0x5000,
    );
    p.f.block_mut(b2).term = Terminator::Return(phi);
    p.f.params = p.cells.clone();
    p.f.ret_ty = Ty::u64();
    let f = p.f;
    if !rdec_core::verify::verify(&f).is_ok() {
        return false;
    }
    let sig = tyinfer::recover(&f);
    sig.params[0].width == Some(Width::W32) && sig.params[1].width.is_none()
}

fn probe_flags_shift_marks_operands() -> bool {
    // `sar` feeding a branch, before jcc fusion: the shift is the signedness
    // witness and the flags arm reads both operands of the shift it defines.
    let mut p = Probe::new(2);
    let (a, n) = (p.cells[0], p.cells[1]);
    let fl = p.ins(Op::Flags(FlagsOp::Sar { a, b: n }), Ty::Flags);
    let sf = p.ins(Op::GetFlag(rdec_core::ir::Flag::SF, fl), Ty::Bool);
    p.split(sf);
    p.finish(a);
    if !rdec_core::verify::verify(&p.f).is_ok() {
        return false;
    }
    let sig = tyinfer::recover(&p.f);
    sig.params[0].sx == Some(Sx::Signed) && sig.params[1].sx == Some(Sx::Signed)
}

fn probe_repeated_evidence_one_fact() -> bool {
    // Same fact, two instructions, one value: the claim is one Signed, and the
    // witness list keeps every statement (the `--explain` audit needs the
    // addresses, not a count).
    let mut p = Probe::new(1);
    let a = p.cells[0];
    p.cell_w32(0);
    let _ = p.ins(Op::Cast(CastKind::SExt, Ty::u64(), a), Ty::u64());
    // The `idiv` reads the same 32-bit cell: equal widths, or the verifier
    // (rightly) refuses the fixture before the claim is ever folded.
    let d = p.ins(Op::Const(3), Ty::u32());
    let q = p.ins(Op::Bin(BinOp::SDiv, a, d), Ty::u32());
    p.finish(q);
    if !rdec_core::verify::verify(&p.f).is_ok() {
        return false;
    }
    let sig = tyinfer::recover(&p.f);
    let c = &sig.params[0];
    c.sx == Some(Sx::Signed)
        && sig
            .fact_witness
            .get(a as usize)
            .map(|w| w.iter().filter(|s| s.fact == tyinfer::Fact::Signed).count() >= 2)
            .unwrap_or(false)
}

fn probe_conflict_prints_silence() -> bool {
    // `sar` beside `shr` on one value (`shift_all.c`): the source had a CAST
    // there, not a type. Silence + a loud conflict is the only honest answer.
    let mut p = Probe::new(1);
    let a = p.cells[0];
    let one = konst(&mut p, 1);
    let s = p.ins(Op::Bin(BinOp::Sar, a, one), Ty::u64());
    let u = p.ins(Op::Bin(BinOp::Shr, a, one), Ty::u64());
    let any = p.ins(Op::Bin(BinOp::Xor, s, u), Ty::u64());
    p.finish(any);
    if !rdec_core::verify::verify(&p.f).is_ok() {
        return false;
    }
    let sig = tyinfer::recover(&p.f);
    let c = &sig.params[0];
    c.sx.is_none() && c.sx_conflict && c.is_silent()
}

fn probe_unforced_claim_prints_nothing() -> bool {
    // The ABI lower bound of the drill: an `add` on the incoming cell reads
    // the cell and signs nothing. `is_silent()` is the display contract — a
    // merge that printed a default type here is what `--corpus` scores as LIE.
    let mut p = Probe::new(1);
    let a = p.cells[0];
    let one = konst(&mut p, 1);
    let s = p.ins(Op::Bin(BinOp::Add, a, one), Ty::u64());
    p.finish(s);
    if !rdec_core::verify::verify(&p.f).is_ok() {
        return false;
    }
    tyinfer::recover(&p.f).params[0].is_silent()
}

pub fn types_selftest() -> i32 {
    // (rule, probe). Every entry binds one rule of the recovery module.
    let oks: Vec<(&str, bool)> = vec![
        (
            "tyinfer: movzx zero-extends, proving an unsigned source",
            probe_zext(),
        ),
        (
            "tyinfer: movsx sign-extends, proving a signed source",
            probe_sext(),
        ),
        (
            "tyinfer: shr with a zero fill proves unsigned; sar proves signed",
            probe_shr_zero_fill(),
        ),
        ("tyinfer: sdiv proves a signed dividend", probe_sdiv()),
        ("tyinfer: udiv proves an unsigned dividend", probe_udiv()),
        (
            "tyinfer: a signed compare signs both operands signed",
            probe_cmp(IntCmp::Lt),
        ),
        (
            "tyinfer: an unsigned compare signs both operands unsigned",
            probe_cmp(IntCmp::Ult),
        ),
        (
            "tyinfer: signed-to-float proves a signed source",
            probe_sitofp(),
        ),
        (
            "tyinfer: unsigned-to-float proves an unsigned source",
            probe_uitofp(),
        ),
        (
            "tyinfer: pointerness comes from dereference, not from addition",
            probe_ptr_from_deref(),
        ),
        (
            "tyinfer: pointer + constant stays a pointer",
            probe_ptr_plus_const(),
        ),
        (
            "tyinfer: a slot links the value stored to the value loaded",
            probe_slot_link(),
        ),
        (
            "tyinfer: a 32-bit cell read with sign-extension forces a w32 width claim",
            probe_cell32_sext_width(),
        ),
        (
            "tyinfer: a W64 cell read only at W64 forces no width claim",
            probe_w64_read_no_width(),
        ),
        (
            "tyinfer: a 32-bit spill of a value feeds the cell width back",
            probe_spill_bounds_width(),
        ),
        (
            "tyinfer: signedness does not leak across slots",
            probe_signedness_does_not_leak_across_slots(),
        ),
        (
            "tyinfer: every width claim carries its read-width witnesses",
            probe_width_claim_carries_witness(),
        ),
        (
            "tyinfer: a width bound does not travel across an SSA phi",
            probe_width_stops_at_phi(),
        ),
        (
            "tyinfer: sar beside shr on one value is a conflict printed as silence",
            probe_conflict_prints_silence(),
        ),
        (
            "tyinfer: flags shifts mark operands",
            probe_flags_shift_marks_operands(),
        ),
        (
            "tyinfer: repeated evidence for one fact is recorded, not collapsed",
            probe_repeated_evidence_one_fact(),
        ),
        (
            "abi: an unforced claim prints nothing",
            probe_unforced_claim_prints_nothing(),
        ),
    ];
    for (name, ok) in oks.iter() {
        println!("{}  {}", if *ok { "ok   " } else { "FAIL " }, name);
    }

    // Integrity gates: a battery can only print its own count, so the count
    // and the constants it is measured against are pinned here, not in prose.
    let claims = tyinfer::FACT_CLAIMS_TOTAL > 0 && tyinfer::ABI_RECOVERY_SITES > 0;
    println!(
        "{}  register: fact claims and recovery sites pinned",
        if claims { "ok   " } else { "FAIL " }
    );
    let battery = oks.len() == tyinfer::PROBE_RULES_TOTAL;
    println!(
        "{}  register: battery size pinned ({})",
        if battery { "ok   " } else { "FAIL " },
        tyinfer::PROBE_RULES_TOTAL
    );
    let sites = tyinfer::ABI_RECOVERY_SITES == 172;
    println!(
        "{}  admin: recovery sites (172) pinned",
        if sites { "ok   " } else { "FAIL " }
    );
    // The CI form of the corpus gate (`types --corpus --baseline`) reads this file,
    // so the battery pins it the way it pins its own size: a baseline that does not
    // parse, is empty, or names a family the scorer cannot print turns the CI step
    // into a printout that cannot go red.
    let baseline_ok = match load_types_baseline(".gate/types-baseline") {
        Ok(w) => w.keys().all(|k| !k.starts_with("UNMAPPED(")),
        Err(e) => {
            println!("(types baseline: {e})");
            false
        }
    };
    println!(
        "{}  register: types baseline parses and names printable families",
        if baseline_ok { "ok   " } else { "FAIL " }
    );

    let n = oks.iter().filter(|(_, ok)| *ok).count();
    println!(
        "fact-rule probes: {n}/{} ok (battery {}), register {}/4",
        tyinfer::PROBE_RULES_TOTAL,
        oks.len(),
        usize::from(claims) + usize::from(battery) + usize::from(sites) + usize::from(baseline_ok),
    );
    let red = oks.iter().filter(|(_, ok)| !*ok).count()
        + usize::from(!claims)
        + usize::from(!battery)
        + usize::from(!sites)
        + usize::from(!baseline_ok);
    if red > 0 || n < tyinfer::PROBE_RULES_TOTAL {
        println!("gate: selftest RED ({red} failed lines)");
        return 1;
    }
    println!("gate: selftest GREEN");
    0
}

#[cfg(test)]
mod baseline_ratchet_tests {
    // The CI step runs `types --corpus --baseline`, so the ratchet is the step that
    // can go red. A ratchet that cannot go red is a comment. Each case below is run
    // against the real comparator, and the two direction cases (RISE, FALL) are the
    // ones that make it a ratchet rather than a printout.
    use super::{
        baseline_arg, families_of, lie_family, load_types_baseline, object_args, ratchet_problems,
    };
    use std::collections::BTreeMap;

    fn map(pairs: &[(&str, usize)]) -> BTreeMap<String, usize> {
        pairs
            .iter()
            .map(|(k, v)| (k.to_string(), *v))
            .collect::<BTreeMap<String, usize>>()
    }

    #[test]
    fn every_lie_class_maps_to_a_family() {
        // The five the scorer can print, plus the (ret) tag the scorer appends.
        assert_eq!(
            lie_family("gcd_loop#p0: prints signed over declared unsigned"),
            "gcd_loop#p0|signedness"
        );
        assert_eq!(
            lie_family("f (ret): reads w64 over declared w32"),
            "f|width"
        );
        assert_eq!(
            lie_family("f#p1: pointer claim over declared int"),
            "f#p1|pointer"
        );
        assert_eq!(
            lie_family("f#p2: float claim F64 over declared f32"),
            "f#p2|float"
        );
        assert_eq!(
            lie_family("carry_chain: return claim over declared void"),
            "carry_chain|void-return"
        );
    }

    #[test]
    fn an_unmapped_lie_text_cannot_match_a_baseline_row() {
        // A new lie CLASS has to be loud: the family it lands in is `UNMAPPED`, and
        // no baseline can name it in advance, so the ratchet goes red on the shape.
        // The census here has no carry_chain lie at all, so the comparator reports
        // BOTH problems: the unnamed new family, and the family the baseline still
        // allows 4 of. One red line per defect, not one per census.
        let got = families_of(&["weird: did something new".to_string()]);
        assert!(got.contains_key("UNMAPPED(did something new)"));
        let problems = ratchet_problems(&got, &map(&[("carry_chain|void-return", 4)]));
        assert_eq!(problems.len(), 2, "{problems:?}");
        assert!(
            problems
                .iter()
                .any(|p| p.starts_with("UNMAPPED(did something new)")
                    && p.contains("NO baseline row")),
            "{problems:?}"
        );
        assert!(
            problems
                .iter()
                .any(|p| p.contains("carry_chain|void-return") && p.contains("census has 0")),
            "{problems:?}"
        );
    }

    #[test]
    fn exact_match_is_green() {
        let got = families_of(&vec![
            "carry_chain: return claim over declared void"
                .to_string();
            4
        ]);
        assert_eq!(got.get("carry_chain|void-return"), Some(&4));
        assert!(ratchet_problems(&got, &map(&[("carry_chain|void-return", 4)])).is_empty());
    }

    #[test]
    fn a_rise_is_red() {
        // The sabotage direction: one more void-return lie than the baseline names.
        let got = families_of(&vec![
            "carry_chain: return claim over declared void"
                .to_string();
            5
        ]);
        let problems = ratchet_problems(&got, &map(&[("carry_chain|void-return", 4)]));
        assert_eq!(problems.len(), 1, "a rise must be red, got {problems:?}");
        assert!(
            problems[0].contains("NEW over-truth claims"),
            "{problems:?}"
        );
    }

    #[test]
    fn a_fall_is_red_too() {
        // Fixed the family? The commit lowers the baseline in the same change —
        // otherwise a silent drift turns a census into a memory.
        let got = families_of(&vec![
            "carry_chain: return claim over declared void"
                .to_string();
            3
        ]);
        let problems = ratchet_problems(&got, &map(&[("carry_chain|void-return", 4)]));
        assert_eq!(problems.len(), 1, "a fall must be red, got {problems:?}");
        assert!(problems[0].contains("lower the baseline"), "{problems:?}");
        // And a family that went fully clean has no census line at all.
        let clean = families_of(&[]);
        let problems = ratchet_problems(&clean, &map(&[("carry_chain|void-return", 4)]));
        assert_eq!(problems.len(), 1, "{problems:?}");
        assert!(problems[0].contains("census has 0"), "{problems:?}");
    }

    #[test]
    fn a_new_family_with_no_row_is_red() {
        let got = families_of(&[
            "carry_chain: return claim over declared void".to_string(),
            "cmov_loop#p0: prints unsigned over declared signed".to_string(),
        ]);
        let problems = ratchet_problems(&got, &map(&[("carry_chain|void-return", 1)]));
        assert_eq!(problems.len(), 1, "{problems:?}");
        assert!(problems[0].contains("NO baseline row"), "{problems:?}");
    }

    #[test]
    fn a_missing_or_empty_baseline_is_an_error() {
        let dir = std::env::temp_dir().join("rdec-types-baseline-ratchet");
        std::fs::create_dir_all(&dir).expect("temp dir for a unit test");
        let missing = dir.join("definitely-not-here.tsv");
        assert!(load_types_baseline(missing.to_str().expect("utf-8 path")).is_err());
        let empty = dir.join("empty-baseline");
        std::fs::write(&empty, "# only comments, so it checks nothing\n").expect("write");
        let err = load_types_baseline(empty.to_str().expect("utf-8 path")).err();
        assert!(
            err.as_deref().map(|e| e.contains("empty")).unwrap_or(false),
            "an empty baseline must be an error, got {err:?}"
        );
        let malformed = dir.join("bad-baseline");
        std::fs::write(&malformed, "carry_chain|void-return four\n").expect("write");
        assert!(load_types_baseline(malformed.to_str().expect("utf-8 path")).is_err());
    }

    #[test]
    fn baseline_arg_split_pins_the_baseline_path_value() {
        // Red-first, measured: the first wiring skipped the FLAG's index instead of
        // its VALUE's, so `.gate/types-baseline` was handed to the lifter as an object
        // and the CI form died with "object with a 28515-byte optional header", exit 2.
        let argv = |v: &[&str]| -> Vec<String> { v.iter().map(|s| s.to_string()).collect() };
        let ci = argv(&["types", "--corpus", "--baseline", ".gate/types-baseline"]);
        assert_eq!(
            object_args(&ci),
            Vec::<String>::new(),
            "the baseline path is not an object"
        );
        assert_eq!(
            baseline_arg(&ci).as_deref(),
            Some(".gate/types-baseline"),
            "an explicit --baseline PATH is honoured"
        );
        // A bare `--baseline` takes the default path and adds no object either.
        let bare = argv(&["types", "--corpus", "--baseline"]);
        assert_eq!(baseline_arg(&bare).as_deref(), Some(".gate/types-baseline"));
        assert_eq!(object_args(&bare), Vec::<String>::new());
        // No flag at all: no baseline, and the positional objects survive in order.
        let plain = argv(&["types", "--corpus", "a.obj", "b.obj"]);
        assert_eq!(baseline_arg(&plain), None);
        assert_eq!(
            object_args(&plain),
            vec!["a.obj".to_string(), "b.obj".to_string()]
        );
    }
}
